char* str_a2(int i, char (*a2)[70]){
    if(i<=248){
        return a2[i];
    } else if(i<500){
       return (char*)"Malformed region";
    } else{
        return a2[i-251];
    }
}

void str_dayHour(char*date, int i, char (*days)[10],char (*half_days)[12]){
    if (i==0 || i>=10081){date= (char*)"Malformed time of the week"; return;}
    int t=i-1;
    char* day=days[t/1440];
    char* half_day;
    t = t%1440;
    if (t>720){
        half_day=half_days[1];
        t=t-720;
    } else {
        half_day=half_days[0];
    }
    int hour = t/60;
    int minute = t%60;
    sprintf(date,"%s - %d:%d %s\0",(char*)day,hour,minute, half_day);
}

bool streq(char* str1, char* str2){
    int i=0;
    while(str1[i]!='\0' && str2[i]!='\0' && str1[i]==str2[i]){
        i++;
    }
    if(str1[i]==str2[i]){
        return true;
    }
    return false;
}

char* translate(char* language, int a1_, int a2_, int a4_, int a5_, int a6_, int a7_, int a8_, int a11a_, int a11b_)
{    
    char* msg_eng=(char*)malloc(10000*sizeof(char));
    char (*a1)[15];
    char (*a2)[70];
    char (*a4)[840];
    char (*a5)[60];
    char (*a6)[15];
    char (*a8)[20];
    //char (*a11a)[260];
    //char (*a11b)[510];
    char (*days)[10];
    char (*half_day)[12];

    if(streq(language,(char*)"fr")){
        a1=a1_fr;
        a2=a2_fr;
        a4=a4_fr;
        a5=a5_fr;
        a6=a6_fr;
        a8=a8_fr;
        //a11a=a11a_fr;
        //a11b=a11b_fr;
        days=days_fr;
        half_day=half_day_fr;
    }else{
        a1=a1_eng;
        a2=a2_eng;
        a4=a4_eng;
        a5=a5_eng;
        a6=a6_eng;
        a8=a8_eng;
        //a11a=a11a_eng;
        //a11b=a11b_eng;
        days=days_eng;
        half_day=half_day_eng;
    }

    char* typeMsg=a1[a1_];
    char* region=str_a2(a2_,a2);
    char* onsetWeek=a6[a6_];
    char dayHour[50];
    str_dayHour(dayHour,a7_,days,half_day);
    char* hazardType=a4[a4_];
    char* severity=a5[a5_];
    char* duration=a8[a8_];
    //char* guidanceInstructionA=a11a[a11a_];
    //char* guidanceInstructionB=a11b[a11b_];

    sprintf(msg_eng,"%s\n%s\n%s week\n%s\n%s\nSeverity: %s\n%s\n\0", typeMsg, region, onsetWeek, dayHour, hazardType, severity, duration);

    /*if(streq(language,(char*)"fr")){
        sprintf(msg_eng,"%s\n%s\nSemaine %s\n%s\n%s\nGravité: %s\n%s\n%s\n%s\0", typeMsg, region, onsetWeek, dayHour, hazardType, severity, duration, guidanceInstructionA, guidanceInstructionB);
    }else{
        sprintf(msg_eng,"%s\n%s\n%s week\n%s\n%s\nSeverity: %s\n%s\n%s\n%s\0", typeMsg, region, onsetWeek, dayHour, hazardType, severity, duration, guidanceInstructionA, guidanceInstructionB);
    }*/
    return msg_eng;

}

